/* Expected slot mutations are generated by complete original Mercs DOS and
 * Windows critical/cook-off execution. Include the private dispatcher to
 * avoid probabilistic damage setup. */
#include <assert.h>
#include <stdio.h>
#include <string.h>
#include "../src/combat.c"
#include "../tests/fixtures/combat-completion/original-ammunition.h"

static void check(const mercs_ammunition_case *c)
{
    combat_unit u;
    int i,k;
    memset(&u,0,sizeof u);
    combat_damage_live=c->live;
    u.ammo_pool_count=c->pool_n;
    for(i=0;i<c->pool_n;i++) { u.ammo_pools[i].weapon=i+1;u.ammo_pools[i].rounds=c->pools[i]; }
    u.bin_count=c->bin_n;
    for(i=0;i<c->bin_n;i++) {
        u.bins[i].id=(uint32_t)c->bin_id[i];u.bins[i].rounds=c->bin_rounds[i];
        u.bins[i].critical_pool=c->bin_pool[i];
    }
    for(i=0;i<8;i++) {
        u.internal[i]=100;u.loc_gone[i]=c->gone[i];u.slot_count[i]=c->counts[i];
        for(k=0;k<12;k++)u.slots[i][k]=(uint32_t)c->slots[i][k];
    }
    if(c->kind)crit_item(&u,c->location+1,c->index,c->silent);else cook_off(&u);
    if(u.destroyed!=c->want_destroyed)fprintf(stderr,"%s: destruction mismatch\n",c->name);
    assert(u.destroyed==c->want_destroyed);
    for(i=0;i<8;i++) {
        if(u.slot_count[i]!=c->want_counts[i])fprintf(stderr,"%s: location %d count mismatch\n",c->name,i);
        assert(u.slot_count[i]==c->want_counts[i]);assert(u.internal[i]==100);
        for(k=0;k<12;k++)assert(u.slots[i][k]==(uint32_t)c->want_slots[i][k]);
    }
    for(i=0;i<c->bin_n;i++)assert(u.bins[i].rounds==c->bin_rounds[i]);
    for(i=0;i<c->pool_n;i++)assert(u.ammo_pools[i].rounds==c->pools[i]);
    assert(!u.ammo_blown&&!u.ammo_boom_loc&&!u.red_flash&&!u.ejected);
}

int main(void)
{
    size_t i;
    combat_unit u;
    for(i=0;i<sizeof mercs_ammunition_cases/sizeof mercs_ammunition_cases[0];i++)check(&mercs_ammunition_cases[i]);
    /* Corrupt native indices have an explicit bounded result; no original
     * out-of-range memory behavior is claimed. */
    memset(&u,0,sizeof u);u.ammo_pool_count=1;u.ammo_pools[0].rounds=10;
    u.bin_count=1;u.bins[0].id=10101;u.bins[0].critical_pool=-1;
    u.slot_count[0]=1;u.slots[0][0]=10101;combat_damage_live=1;
    cook_off(&u);assert(u.destroyed&&u.slot_count[0]==1);
    u.destroyed=0;u.bins[0].critical_pool=COMBAT_MAX_POOLS;
    cook_off(&u);assert(u.destroyed&&u.slot_count[0]==1);
    u.destroyed=0;u.human=1;u.invulnerable=1;cook_off(&u);assert(!u.destroyed);
    combat_damage_live=1;
    printf("PASS: %zu ammunition outcomes shared by 36 original DOS/Windows cases; bounded malformed bins and invulnerability\n",i);
    return 0;
}
